data.policy:
# app-secrets: deploy bot's grants

# read-only config
path "secret/data/app/config" {
  capabilities = ["read", "list"]
}

# full CRUD on the app's runtime secrets
path "secret/data/app/runtime/*" {
  capabilities = ["create", "read", "update", "delete", "list"]
}

# write-only audit drop
path "secret/data/app/audit" {
  capabilities = ["create", "update"]
}

# explicitly denied path — must NOT become a grant
path "secret/data/app/forbidden" {
  capabilities = ["deny"]
}
